// Canonical wire-byte fixtures for Marlin BFT Mark II packets, plus
// Fletcher-16 vectors. Hand-derived from the protocol spec and cross-checked
// against the Python reference at
// https://github.com/trippwill/marlin-binary-protocol (MIT).
//
// Tests verify these against the Rust encoder in `tests/codec_roundtrip.rs`,
// so any drift between the spec and our implementation is caught on every
// run of `cargo test`.

/// Marlin BFT packet start token (little-endian on the wire).
pub const PACKET_TOKEN: u16 = 0xB5AD;

/// Control SYNC: proto=0, type=1, sync=0, no payload. First binary packet sent after the host's `M28B1\n` ASCII trigger.
pub const SYNC_PACKET: &[u8] = &[0xAD, 0xB5, 0x00, 0x01, 0x00, 0x00, 0x01, 0x03];

/// Control CLOSE: proto=0, type=2, sync=1, no payload.
pub const CONTROL_CLOSE_PACKET: &[u8] = &[0xAD, 0xB5, 0x01, 0x02, 0x00, 0x00, 0x03, 0x0A];

/// File QUERY: proto=1, type=0, sync=0, no payload.
pub const QUERY_PACKET: &[u8] = &[0xAD, 0xB5, 0x00, 0x10, 0x00, 0x00, 0x10, 0x30];

/// File OPEN: proto=1, type=1, sync=1, payload = [dummy=0, compression=0, b"test.gco\0"].
pub const OPEN_PACKET: &[u8] = &[
    0xAD, 0xB5, 0x01, 0x11, 0x0B, 0x00, 0x1D, 0x4D, 0x00, 0x00, 0x74, 0x65, 0x73, 0x74, 0x2E, 0x67,
    0x63, 0x6F, 0x00, 0xB1, 0x95,
];

/// File WRITE: proto=1, type=3, sync=2, payload = b"hello".
pub const WRITE_PACKET: &[u8] = &[
    0xAD, 0xB5, 0x02, 0x13, 0x05, 0x00, 0x1A, 0x4B, 0x68, 0x65, 0x6C, 0x6C, 0x6F, 0x95, 0xA9,
];

/// File CLOSE: proto=1, type=2, sync=3, no payload.
pub const CLOSE_FILE_PACKET: &[u8] = &[0xAD, 0xB5, 0x03, 0x12, 0x00, 0x00, 0x15, 0x42];

/// File ABORT: proto=1, type=4, sync=4, no payload.
pub const ABORT_PACKET: &[u8] = &[0xAD, 0xB5, 0x04, 0x14, 0x00, 0x00, 0x18, 0x4C];

/// Fletcher-16 (mod 255) test vectors: (input, expected u16).
pub const FLETCHER16_VECTORS: &[(&[u8], u16)] = &[
    (&[], 0x0000),                 // FLETCHER16_EMPTY
    (&[0x00], 0x0000),             // FLETCHER16_ZERO
    (&[0x61, 0x62, 0x63], 0x4C27), // FLETCHER16_ABC
    (&[0xFF], 0x0000),             // FLETCHER16_FF
    (
        &[
            0x54, 0x68, 0x65, 0x20, 0x71, 0x75, 0x69, 0x63, 0x6B, 0x20, 0x62, 0x72, 0x6F, 0x77,
            0x6E, 0x20, 0x66, 0x6F, 0x78, 0x20, 0x6A, 0x75, 0x6D, 0x70, 0x73, 0x20, 0x6F, 0x76,
            0x65, 0x72, 0x20, 0x74, 0x68, 0x65, 0x20, 0x6C, 0x61, 0x7A, 0x79, 0x20, 0x64, 0x6F,
            0x67,
        ],
        0xFEE8,
    ), // FLETCHER16_LONG
];
